Node* current = root;
while (current != nullptr && !current->is_leaf) {
    // Binary search on internal node to find the right child
    int left = 0;
    int right = current->num_keys - 1;
    int mid;

    while (left <= right) {
        mid = left + (right - left) / 2;
        if (current->keys[mid] < key) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    // After binary search, left is the position where we should go
    // left is the index of the first key >= key, so we go to children[left]
    current = current->children[left];
}

// Now we're at a leaf node
if (current != nullptr) {
    // Binary search in leaf node
    int left = 0;
    int right = current->num_keys - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (current->keys[mid] == key) {
            return true;
        } else if (current->keys[mid] < key) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
}

return false;

